public int sum(int a, int b) {
  return a + b;
}
private double average(int a, int b) {
  return (a + b) / 2;
}
public int randomNumber(int x) {
  return (int) (x * Math.random());
}
public int randomNumber(int a, int b) {
  return (int) (a + Math.random(b - a));
}
public boolean canSleepIn(boolean isWeekday, boolean isVacation) {
  return !isWeekday || isVacation;
}
public boolean getsSpeedingTicket(double mph, boolean copIsGrouchy) {
  return mph > 70 || (copIsGrouchy && mph > 65);
}
public String slug(String a, String b, String c) {
  return (a.toLowerCase() + '-' + b.toLowerCase() + '-' + c.toLowerCase());
}
public String middle(String x) {
  int quarter = (int) (x.length() * 0.25);
  return x.substring(quarter, 3 * quarter);
}
public int sum(int[] ints) {
  int sum = 0;
  for (int i = 0; i < ints.length; i++) {
    sum += ints[i];
  }
  return sum;
}
public double average(int[] ints) {
  double avg = 0;
  for (int i = 0; i < ints.length; i++) {
    avg += i;
  }
  avg /= ints.length
  return avg;
}
public Object randomChoice(Object[] objs) {
  int index = (int) ((objs.length - 1) * Math.random());
  return objs[index];
}
public class Greeter {

  private Greeter greeter;
  private String greeting;
  private int times;

  public Greeter(String greeting) {
    this.greeting = greeting;
    times = 0;
  }

  public void greet() {
    times++;
    System.out.println(greeting + ".");
  }

  public void greet(String name) {
    times++;
    System.out.println(greeting + ", " + name + ".");
  }

  public int greetings() {
    return times;
  }

  public static void main(String[] args) {
    greeter = new Greeter("hello");
    greeter.greet();
    greeter.greet("Mr. Seibel");
    greeter.times();
  }
}
public class PigLatinGreeter extends Greeter {

  private PigLatinGreeter greeter;
  private String greeting;
  private int times;

  public PigLatinGreeter(String greeting) {
    this.greeting = toPigLatin(greeting);
    times = 0;
  }

  @Override
  public void greet(String name) {
    times++;
    System.out.println(greeting + ", " + toPigLatin(name) + ".");
  }

  private String toPigLatin(String x) {
    return x.substring(1, x.length - 1) + x.charAt(0) + "ay";
  }

  public static void main(String[] args) {
    greeter = new PigLatinGreeter("hello");
    greeter.greet();
    greeter.greet("Mr. Seibel");
    greeter.times();
  }
}
